exercise.solution:
import numpy as np

def forward_report(X, W1, b1, W2, b2, targets):
    h=np.maximum(0,np.asarray(X,dtype=float)@np.asarray(W1)+np.asarray(b1))
    p=h@np.asarray(W2)+np.asarray(b2)
    return {"hidden":h.tolist(),"predictions":p.tolist(),"loss":float(np.mean((p-np.asarray(targets))**2))}

