import numpy as np

def dense_backward(X, W, G):
    X=np.asarray(X,dtype=float); W=np.asarray(W,dtype=float); G=np.asarray(G,dtype=float)
    return G@W.T,X.T@G,G.sum(axis=0)

def train_step_report(x, y, w, b, rate):
    e=[w*a+b-t for a,t in zip(x,y)]
    dw=2*sum(v*a for v,a in zip(e,x))/len(x)
    db=2*sum(e)/len(x)
    nw,nb=w-rate*dw,b-rate*db
    return {"w":nw,"b":nb,"before":sum(v*v for v in e)/len(e),"after":sum((nw*a+nb-t)**2 for a,t in zip(x,y))/len(y)}

