exercise.solution:
import numpy as np

def residual_norm(x, update, eps=1e-5):
    z=np.asarray(x,dtype=float)+np.asarray(update,dtype=float)
    mean=z.mean(axis=-1,keepdims=True)
    variance=((z-mean)**2).mean(axis=-1,keepdims=True)
    return (z-mean)/np.sqrt(variance+eps)

