exercise.solution:
import numpy as np

def network_forward(X, state):
    X=np.asarray(X,dtype=float)
    h=np.tanh(X@state["W1"]+state["b1"])
    logits=h@state["W2"]+state["b2"]
    p=1/(1+np.exp(-np.clip(logits,-500,500)))
    return h,p

def network_gradients(X, y, state):
    X=np.asarray(X,dtype=float); y=np.asarray(y,dtype=float).reshape(-1,1)
    h,p=network_forward(X,state)
    dz=(p-y)/len(X)
    dh=(dz@state["W2"].T)*(1-h*h)
    return {"W1":X.T@dh,"b1":dh.sum(axis=0),"W2":h.T@dz,"b2":dz.sum(axis=0)}

def init_state(seed=7):
    rng=np.random.default_rng(seed)
    return {"W1":rng.normal(0,1,(2,4)),"b1":np.zeros(4),"W2":rng.normal(0,1,(4,1)),"b2":np.zeros(1)}

def train_xor(steps=1000, rate=0.8, seed=7):
    X=np.array([[0.,0.],[0.,1.],[1.,0.],[1.,1.]])
    y=np.array([[0.],[1.],[1.],[0.]])
    state=init_state(seed)
    def loss():
        p=np.clip(network_forward(X,state)[1],1e-12,1-1e-12)
        return float(-np.mean(y*np.log(p)+(1-y)*np.log(1-p)))
    losses=[loss()]
    for _ in range(steps):
        grads=network_gradients(X,y,state)
        state={k:v-rate*grads[k] for k,v in state.items()}
        losses.append(loss())
    return {"state":state,"probabilities":network_forward(X,state)[1],"losses":losses}
